<template>
  <div class="demo-root" :class="{ itsco: data?.agency.slug === 'itsco' }">
    <header class="demo-toolbar">
      <div><strong>Plotline · Experience the journey</strong><small>Fictional Alex Demo · Online rehearsal · No emails, employment records or payroll</small></div>
      <details><summary>Demo controls</summary><div class="demo-controls">
        <strong>ITSCO</strong>
        <label>Role<select v-model="role" aria-label="Role"><option value="facilitator">Bachelor’s-level facilitator</option><option value="provider">Licensed provider</option><option value="intern">Student intern</option><option value="staff">Administrative staff</option></select></label>
        <label v-if="company === 'itsco'"><input v-model="school" type="checkbox" /> Expected to work in schools</label>
        <button @click="reset('prehire')">Start fresh prehire</button><button @click="reset('onboarding')">Start fresh onboarding</button>
        <button @click="view='packet'">Open real job packet</button><p>Starting fresh resets this tab’s demo. Refreshing starts a new rehearsal. Use fictional information only. File uploads are disabled; use the sample avatar step.</p>
      </div></details>
    </header>
    <nav class="demo-navigation" aria-label="Rehearsal shortcuts"><button @click="reset('prehire')">Restart prehire</button><button @click="reset('onboarding')">Jump to onboarding</button><button @click="skip">Jump to completed checklist</button><button @click="view='packet'">Real job &amp; contract</button></nav><p v-if="error" role="alert" class="demo-error">{{ error }}</p>
    <p v-if="!data" class="demo-panel">Opening your demo…</p>
    <template v-else>
      <nav class="demo-navigation" aria-label="Demo workspace">
        <button v-for="tab in tabs" :key="tab.id" :aria-pressed="view === tab.id" @click="view = tab.id; refresh()">{{ tab.label }}</button>
        <span>{{ data.candidate.status === 'PREHIRE_OPEN' ? 'Prehire in progress' : data.candidate.status === 'PREHIRE_REVIEW' ? 'Prehire awaiting review' : data.demo.activated ? 'Employee experience' : data.journey.onboardingCompletedAt ? 'Onboarding awaiting review' : 'Onboarding in progress' }}</span>
      </nav>
      <div v-if="notice" role="status" class="demo-notice">{{ notice }}</div>
      <HirePacketPreview :agency-id-override="bundle.agency.id" v-show="view==='packet'" @ready="packetReady" /><Workspace v-if="view === 'portal'" :key="generation" :data="data" token="demo" :http="http" @reload="refresh" @submit="submit" @phase="phase = $event" @section="onSection">
        <template #demo-check="{ step, closed }">
          <section class="demo-panel">
            <p class="eyebrow">Simulated form · No real submission</p>
            <h3>{{ step.title }}</h3><button v-if="['background','agreement','job-description'].includes(step.key)" @click="view='packet'">Review actual ITSCO documents and pay configuration</button><p v-if="packetTitle">Selected posting: {{ packetTitle }}</p><p>{{ explanations[step.key] }}</p>
            <div v-if="step.key === 'headshot'" class="sample-avatar" aria-label="Sample avatar">AD</div>
            <dl v-else-if="step.key === 'background'"><dt>Applicant</dt><dd>Alex Demo</dd><dt>Screening information</dt><dd>Fictional sample only · No identity numbers collected</dd></dl>
            <p v-if="step.key === 'agreement'">This is a demonstration acknowledgment, not an employment offer or a legal contract. The live flow uses the agency’s assigned agreement.</p>
            <p v-if="step.key === 'student-agreement'">Review the student agreement and evaluation appendices in the handbook. The supervision milestone is 60 individual hours completed plus 40 group opportunities offered.</p>
            <p v-if="step.key === 'job-description'">{{ data.candidate.appliedRole }} · Work within documented education, training and approved scope. Clinical oversight and authorization remain separate from training completion.</p>
            <label v-if="!closed && !step.complete"><input v-model="confirmed" type="checkbox" /> I have reviewed this demo step.</label>
            <button v-if="!closed && !step.complete" :disabled="!confirmed || busy" @click="saveSample(step)">{{ step.key === 'headshot' ? 'Use sample avatar' : 'Save demo acknowledgment' }}</button>
            <p v-else>✓ Demo record retained for review.</p>
          </section>
        </template>
        <template #time><p>{{ Math.floor(data.demo.seconds / 60) }}m {{ data.demo.seconds % 60 }}s of active guide training recorded in this demo.</p><p>Assigned lessons use the real activity timer. Optional practice is unpaid. This demo never creates a payroll claim.</p></template>
        <template #documents><section class="demo-panel"><h2>Your library stays with you</h2><p>The handbook is available before hire. Company guides and learning stay accessible during onboarding and afterward.</p><button @click="view = 'library'">Open document library</button></section></template>
        <template #messages><section class="demo-panel"><h2>Messages · Demo only</h2><p>Try writing a question to People Operations. It stays in this rehearsal and is not delivered.</p><article v-for="(message,i) in data.demo.messages" :key="i"><strong>Alex Demo</strong><p>{{ message.text }}</p><small>Saved in this rehearsal · Not sent</small></article><form @submit.prevent="sendMessage"><label>Demo message<textarea v-model="message" required maxlength="2000" /></label><button>Save demo message</button></form></section></template>
      </Workspace>
      <main v-else-if="view === 'library'" class="demo-library">
        <header><p class="eyebrow">{{ data.agency.name }} · Reference library</p><h1>Your documents, in one place.</h1><p>{{ prehire ? 'Your workplace handbook is available to read, search and reference before hire.' : 'Current company guides, policies and resources. Required learning uses these same documents.' }}</p><p class="demo-notice">Q&amp;A uses a clearly labeled local passage lookup here. Live AI and document downloads are disabled in this rehearsal.</p></header>
        <template v-if="!book"><label class="search-label">Find a document<input v-model="search" type="search" placeholder="Search titles and descriptions" /></label><div class="library-grid"><article v-for="entry in library" :key="entry.key"><small>{{ entry.key === 'workplace-handbook' ? 'Workplace policies' : data.demo.required.includes(entry.key) ? 'Required learning for this role' : 'Reference resource' }}</small><h2>{{ entry.title }}</h2><p>{{ entry.description }}</p><button @click="openBook(entry.key)">Read &amp; search</button></article></div></template>
        <template v-else><button @click="book = null">← All documents</button><Book :key="book.metadata.documentKey" ref="bookRef" :handbook="book" :updates="book.updates || []" :answer-question="ask" assistant-preview :analytics-http="http" :analytics="{agencyId:data.agency.id,apiBase:'/document-analytics',surface:prehire?'prehire':'library'}" @handbook-link="openHandbook" /></template>
      </main>
      <main v-else-if="view === 'learning' || view === 'practice'" class="demo-library">
        <h1>{{ view === 'learning' ? 'Your assigned learning' : 'Practice whenever you like' }}</h1><p>Demonstration only · Active assigned time is simulated locally; no pay is posted.</p><p>Use the guide’s search, source links and reading checklist. Answers are checked against the current course’s actual questions.</p>
        <Catalog :key="`${generation}:${view}:${catalogGeneration}`" :agency-id="data.agency.id" :mode="view === 'practice' ? 'on-demand' : 'assigned'" :http="http" api-base="/prehire-portal/demo/document-learning" @completed="refresh" @handbook-link="openHandbook" />
      </main>
      <main v-else-if="view === 'form'" class="demo-library">
        <p class="eyebrow">Click directly on the document</p><h1>Try the fillable form.</h1><p>Click a highlighted field on this blank I-9, type a fictional answer, or select a checkbox. Use Next field and zoom as needed. This is a rehearsal; no I-9 is submitted.</p>
        <button @click="formValues = {}">Clear sample answers</button><p>{{ Object.values(formValues).filter(Boolean).length }} sample answers entered in this tab.</p>
        <PDFEditor :pdf-url="i9Url" :field-definitions="visibleFormFields" v-model:field-values="formValues" />
      </main>
      <main v-else-if="view === 'review'" class="demo-library">
        <p class="eyebrow">Administrator simulation</p><h1>See the other side of the handoff.</h1><p>Review Alex’s progress and advance the fictional account once required work is complete.</p>
        <div class="library-grid"><article><h2>Prehire</h2><p>{{ data.workflow.progress.pre_hire.completed }} of {{ data.workflow.progress.pre_hire.total }} required steps complete</p><button :disabled="data.candidate.status !== 'PREHIRE_REVIEW'" @click="advance">Approve demo prehire → Onboarding</button></article><article><h2>Onboarding</h2><p>{{ data.workflow.progress.onboarding.completed }} of {{ data.workflow.progress.onboarding.total }} required steps complete</p><button :disabled="!data.journey.onboardingCompletedAt || data.demo.activated" @click="advance">Approve demo onboarding → Employee</button></article><article><h2>Paid refresher</h2><p>Supervisor/admin assignments are paid. Optional retakes stay unpaid.</p><label>Guide<select v-model="assignment"><option v-for="key in data.demo.required" :key="key" :value="key">{{ data.demo.library.find(d => d.key === key)?.title }}</option></select></label><button :disabled="prehire || !assignment" @click="assign">Assign demo refresher</button></article></div>
        <section class="demo-panel"><h2>Test checklist</h2><ol><li>Open prehire, review a job description and save fictional profile information.</li><li>Search the handbook and try a source-linked demo question.</li><li>Submit prehire, then use the admin approval above.</li><li>Review and sign the handbook; read assigned guides and take their quizzes.</li><li>Try an incorrect answer, follow its feedback, then retry.</li><li>Submit onboarding, approve it here, and revisit the library or unpaid practice.</li></ol><p>Background screening, contracts, account provisioning, communication consent and supervisor meetings use labeled sample acknowledgments. No real screening, signature transaction, account activation, scheduling or payroll integration is exercised.</p></section>
        <section class="demo-panel"><h2>Activity in this demo</h2><p>{{ data.demo.analytics.filter(e => e.type === 'open').length }} document opens · {{ data.demo.analytics.filter(e => e.type === 'question').length }} questions · {{ data.demo.analytics.filter(e => e.type === 'link').length }} link clicks · {{ data.demo.seconds }} active paid-training seconds</p><p>Document engagement is separate from payroll time.</p><details><summary>Document events &amp; questions</summary><ul><li v-for="(event,i) in data.demo.analytics" :key="i">{{ event.type }} · {{ event.documentKey || event.section }} {{ event.question || event.href }}</li></ul></details><ol><li v-for="(event,i) in data.demo.audit" :key="i">{{ event.action }}</li></ol></section>
      </main>
    </template>
  </div>
</template>
<script setup>
import { computed, ref, onMounted, nextTick } from 'vue';
import {createHireRehearsalEngine} from './hireEngine';
import HirePacketPreview from '../../views/admin/HirePacketPreviewView.vue';

import Workspace from '../prehire/HirePortalWorkspace.vue';
import Book from '../handbook/WorkplaceHandbookBook.vue';
import PDFEditor from '../documents/PDFDocumentFillEditor.vue';
import Catalog from '../training/DocumentLearningCatalog.vue';
const props=defineProps({bundle:Object,i9Url:String,entry:{type:String,default:'prehire'}});
const http=createHireRehearsalEngine(props.bundle);
const packetTitle=ref('');
function packetReady(packet){packetTitle.value=packet.title;}
async function skip(){await run(async()=>{accept((await http.post('/skip')).data);generation.value++;view.value='portal';notice.value='Rehearsal checklist completed. No real training credit or pay was created.';});}
const data=ref(null), company=ref('itsco'), role=ref('facilitator'), school=ref(true), phase=ref('pre_hire'), view=ref('portal'), generation=ref(0), catalogGeneration=ref(0), error=ref(''), notice=ref(''), busy=ref(false), confirmed=ref(false), search=ref(''), book=ref(null), bookKey=ref(''), bookRef=ref(null), assignment=ref('provider-guide'), message=ref('');
const formFields=ref([]), formValues=ref({});
const visibleFormFields=computed(()=>formFields.value.filter(f=>!f.showIf?.fieldId || String(formValues.value[f.showIf.fieldId])===String(f.showIf.equals)));

const prehire=computed(()=>data.value?.candidate.status !== 'ONBOARDING');
const tabs=computed(()=>[{id:'portal',label:'Candidate portal'},{id:'library',label:'Document library'},...(!prehire.value?[{id:'learning',label:'Assigned learning'},{id:'practice',label:'On-demand · Unpaid'}]:[]),{id:'packet',label:'Real job packet'},{id:'form',label:'Clickable form'},{id:'review',label:'Admin review & test log'}]);
const library=computed(()=>(data.value?.demo.library||[]).filter(d=>(!prehire.value||d.key==='workplace-handbook')&&`${d.title} ${d.description}`.toLowerCase().includes(search.value.toLowerCase())));
const explanations={background:'Review the screening step with a fictional applicant. Use the sample acknowledgment; do not enter actual identity information.', 'job-description':'Review the role expectations and acknowledge that you understand them.',agreement:'Practice the agreement handoff with a clearly fictional document.',headshot:'Use the sample initials avatar so no personal photo is needed.',account:'Sample work login: alex.demo@example.test. Your demo supervisor is Taylor Morgan. A live account would be provisioned by People Operations.',communications:'In the live flow, you choose your email and texting preferences and review the applicable consent. This sample acknowledgment changes no subscriptions.','student-agreement':'Practice reviewing the student training and supervision agreement.',orientation:'Your supervisor confirms assignments, scope, facilities access and support contacts. This acknowledgment represents a completed demo orientation; it books no meeting.'};
function accept(value){value.portalLink=location.origin+location.pathname;data.value=value;company.value=value.agency.slug;role.value=value.demo.role;school.value=value.demo.school;}
async function run(fn){error.value='';busy.value=true;try{return await fn();}catch(e){error.value=e.response?.data?.error?.message||e.message;}finally{busy.value=false;}}
async function refresh(){await run(async()=>accept((await http.get('/state')).data));}
async function reset(start){await run(async()=>{accept((await http.post('/reset',{company:company.value,role:role.value,school:school.value,phase:start})).data);phase.value=start==='onboarding'?'onboarding':'pre_hire';generation.value++;view.value='portal';book.value=null;notice.value='Fresh fictional journey ready. All prior progress in this tab has been cleared.';});}
async function submit(){await run(async()=>{accept((await http.post('/submit')).data);notice.value='Demo package submitted. Open Admin review & test log to approve the next stage.';});}
async function advance(){await run(async()=>{accept((await http.post('/advance')).data);generation.value++;phase.value='onboarding';view.value='portal';notice.value=data.value.demo.activated?'Demo onboarding approved. The library and optional practice remain available.':'Demo prehire approved. Welcome to onboarding.';});}
async function saveSample(step){await run(async()=>{await http.post(`/prehire-portal/demo/workflow/${step.key}`,{acknowledged:true,complete:true,sample:true});accept((await http.get('/state')).data);confirmed.value=false;});}
function onSection(){confirmed.value=false;}
async function openBook(key){await run(async()=>{book.value=(await http.get('/library',{params:{key}})).data;bookKey.value=key;});}
async function ask(payload,options){return(await http.post('/answer',{...payload,key:bookKey.value},options)).data;}
async function openHandbook(hash){view.value='library';await openBook('workplace-handbook');await nextTick();if(hash)await bookRef.value?.selectSection(hash.replace(/^handbook-/,''),true);}
async function assign(){await run(async()=>{await http.post('/assign',{key:assignment.value});accept((await http.get('/state')).data);catalogGeneration.value++;notice.value='Paid demo refresher assigned. Open Assigned learning to try it.';});}
async function sendMessage(){await run(async()=>{await http.post('/messages',{text:message.value});message.value='';accept((await http.get('/state')).data);});}
onMounted(async()=>{formFields.value=(await http.get('/form')).data.fields.filter(f=>f.type!=='signature');await reset(props.entry);notice.value='Online rehearsal · Supplied agency source documents · Q&A is passage lookup, not live AI. Sample form actions are not real submissions.';});
</script>
<style scoped>
:global(body){margin:0;background:#f5f7f5;color:#20382f;font-family:var(--font-ptco)}:global(*){box-sizing:border-box}.demo-root{--demo-font:var(--font-ptco)}.demo-root.itsco{--demo-font:var(--font-itsco)}.demo-root :deep(.hire-workspace){font-family:var(--demo-font)}.demo-toolbar{background:#172d2b;color:#fff;padding:15px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px;font-size:13px}.demo-toolbar small{display:block;margin-top:6px;color:#d1ded6;line-height:1.6}.demo-toolbar summary{cursor:pointer;white-space:nowrap;padding:10px;border:1px solid #8caaa1;border-radius:7px}.demo-controls{position:absolute;right:16px;top:84px;z-index:1000;max-width:min(480px,calc(100vw - 32px));background:#fff;color:#20382f;box-shadow:0 12px 45px #172d2b33;padding:22px;border:1px solid #becfc5;border-radius:12px;display:grid;gap:15px}.demo-controls p{font-size:12px;line-height:1.7}.demo-navigation{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:14px 24px;background:white;border-bottom:1px solid #d7e1da}.demo-navigation span{margin-left:auto;font-size:12px;color:#496052}.demo-navigation [aria-pressed=true]{background:#203f34;color:white}.demo-root button{cursor:pointer}.demo-toolbar button,.demo-navigation button,.demo-panel button,.demo-library>button,.library-grid button{font:inherit;font-size:12px;border:1px solid #b7cabe;background:#fff;color:#244835;padding:11px 15px;border-radius:7px;line-height:1.6}.demo-root button:disabled{opacity:.5;cursor:default}.demo-root button:focus-visible,.demo-root input:focus-visible,.demo-root summary:focus-visible{outline:3px solid #a0be54;outline-offset:3px}.demo-notice{padding:12px 24px;background:#f3efdf;font-size:12px;line-height:1.8;margin:0}.demo-error{background:#ffebe6;color:#832f24;padding:18px}.demo-panel{background:white;border:1px solid #d6e0d9;border-radius:10px;padding:25px;line-height:1.8;min-width:0}.demo-panel p{font-size:13px}.demo-panel label{display:block;margin:18px 0}.demo-panel article{border-bottom:1px solid #d6e0d9;margin-bottom:14px}.demo-panel li{margin:9px 0;font-size:13px;overflow-wrap:anywhere}.demo-panel dd{margin:4px 0 18px}.demo-panel dt{font-weight:bold}.demo-library{max-width:1350px;padding:32px 24px;margin:auto;font-family:var(--demo-font)}.demo-library h1{font-size:clamp(26px,4vw,40px);line-height:1.4}.demo-library header>p{line-height:1.9;font-size:14px}.demo-library>.demo-panel{margin-top:22px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:11px}.library-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:18px;margin:24px 0}.library-grid article{background:white;border:1px solid #d1ddd5;border-radius:12px;padding:25px;display:flex;flex-direction:column;align-items:start;gap:10px}.library-grid h2{font-size:19px;line-height:1.5;margin:0}.library-grid p{font-size:13px;line-height:1.8;margin:0 0 14px}.library-grid small{font-size:11px;color:#556d5d}.library-grid button{margin-top:auto}.demo-controls select,.library-grid select,.search-label input,.demo-panel textarea{width:100%;font:inherit;padding:11px;border:1px solid #b8c8bf;border-radius:7px;background:#fff;margin-top:7px}.search-label{display:block;max-width:600px;margin:24px 0;font-size:13px}.sample-avatar{width:100px;height:100px;display:grid;place-items:center;font-size:35px;border-radius:50%;background:#e2eadb;color:#2f5641;margin:20px 0}.demo-panel textarea{min-height:100px}.demo-root :deep(.assistant-intro){display:none}.demo-root :deep(.hire-main .upload-card){display:none}@media(max-width:650px){.demo-toolbar{padding:12px;align-items:start}.demo-toolbar strong{font-size:12px}.demo-toolbar small{font-size:10px}.demo-navigation{padding:12px;gap:7px}.demo-navigation button{font-size:11px;padding:9px}.demo-navigation span{width:100%;margin:0}.demo-library{padding:20px 12px}.demo-notice{padding:12px}.demo-panel{padding:18px}}
</style>
